//
// A form's edit state (`form(X) : ref(name)`, then `name.dirty` and `name.reset()`), held to the
// case table every client target's runtime is tested against: which two form values are the same
// value. Then the form model over it: editing a shown field makes the form dirty, restoring the
// value clears it, a member the form does not show never makes it dirty, `reset()` puts the opened
// values back and clears the messages, and what a successful submit sent is what the form opened
// with.

import 'dart:convert';

import 'package:cruftfree_client/core/forms.dart';
import 'package:cruftfree_client/state/core/forms.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  const valueCases = <({String opened, String current, bool same})>[
    (opened: '{"name": "Ada"}', current: '{"name": "Ada"}', same: true),
    (opened: '{"name": "Ada"}', current: '{"name": "Ada Lovelace"}', same: false),
    (opened: '{"note": null}', current: '{"note": ""}', same: true),
    (opened: '{"note": null}', current: '{}', same: true),
    (opened: '{"note": ""}', current: '{"note": "x"}', same: false),
    (opened: '{"note": "x"}', current: '{"note": ""}', same: false),
    (opened: '{"code": "007"}', current: '{"code": "7"}', same: false),
    (opened: '{"price": 1250}', current: '{"price": 1250}', same: true),
    (opened: '{"price": 1250}', current: '{"price": 1251}', same: false),
    (opened: '{"price": 12.5}', current: '{"price": 12.50}', same: true),
    (opened: '{"price": 7}', current: '{"price": "7"}', same: false),
    (opened: '{"price": 0}', current: '{"price": null}', same: false),
    (opened: '{"vip": false}', current: '{"vip": null}', same: false),
    (opened: '{"vip": false}', current: '{"vip": false}', same: true),
    (opened: '{"day": "2026-11-03"}', current: '{"day": "2026-11-03"}', same: true),
    (opened: '{"day": "2026-11-03"}', current: '{"day": "2026-11-04"}', same: false),
    (opened: '{"at": "2026-11-03T10:00:00.000Z"}', current: '{"at": "2026-11-03T10:00:00.000Z"}', same: true),
    (opened: '{"at": "2026-11-03T10:00:00.000Z"}', current: '{"at": "2026-11-03T11:00:00.000Z"}', same: false),
    (opened: '{"a": 1, "b": 2}', current: '{"b": 2, "a": 1}', same: true),
    (opened: '{"tags": ["a", "b"]}', current: '{"tags": ["a", "b"]}', same: true),
    (opened: '{"tags": ["a", "b"]}', current: '{"tags": ["b", "a"]}', same: false),
    (opened: '{"tags": ["a"]}', current: '{"tags": ["a", "b"]}', same: false),
    (opened: '{"lines": [{"sku": "x", "qty": 1}]}', current: '{"lines": [{"sku": "x", "qty": 1}]}', same: true),
    (opened: '{"lines": [{"sku": "x", "qty": 1}]}', current: '{"lines": [{"sku": "x", "qty": 2}]}', same: false),
  ];

  for (final c in valueCases) {
    test('${c.opened} against ${c.current} is ${c.same ? 'the same value' : 'a different value'}', () {
      expect(formValuesEqual(jsonDecode(c.opened), jsonDecode(c.current)), c.same);
    });
  }

  CruftFreeFormModel opened() {
    final model = CruftFreeFormModel();
    model.load({
      'title': 'Template',
      'amount': 1250,
      'note': null,
      'customerRef': null,
      'lines': [
        {'sku': 'x'},
      ],
    });
    model.markOpened(const ['title', 'amount', 'note', 'lines', 'lines[]', 'lines[].sku']);
    return model;
  }

  test('a form that has just opened is not dirty', () {
    expect(opened().dirty, false);
  });

  test('editing a shown field makes the form dirty and restoring the value clears it', () {
    final model = opened();
    model.setValue('title', 'Other');
    expect(model.dirty, true);
    model.setValue('title', 'Template');
    expect(model.dirty, false);
  });

  test('an emptied optional field equals one that never had a value', () {
    final model = opened();
    model.setValue('note', '');
    expect(model.dirty, false);
  });

  test('a repeated member compares in order, member by member', () {
    final model = opened();
    model.setValue('lines[0].sku', 'y');
    expect(model.dirty, true);
  });

  test('a member the form does not show never makes it dirty', () {
    final model = opened();
    model.setValue('customerRef', 'fixed-from-code');
    expect(model.dirty, false);
  });

  test('a form that has not loaded is not dirty', () {
    final model = opened();
    model.setValue('title', 'Other');
    model.startLoading();
    expect(model.dirty, false);
  });

  test('restoring the opened values clears the messages and the dirty state', () {
    final model = opened();
    model.setValue('title', 'Other');
    model.formError = 'The server said no.';
    model.restoreOpened();
    expect(model.valueAt('title'), 'Template');
    expect(model.formError, null);
    expect(model.dirty, false);
  });

  test('what a successful submit sent is what the form opened with', () {
    final model = opened();
    model.setValue('title', 'Other');
    expect(model.dirty, true);
    model.markOpened(const ['title', 'amount', 'note', 'lines', 'lines[]', 'lines[].sku']);
    expect(model.dirty, false);
    model.restoreOpened();
    expect(model.valueAt('title'), 'Other');
  });

  test('a handle follows the form it is attached to and resets it', () {
    final model = opened();
    final handle = CruftFreeFormHandle();
    var cleared = 0;
    handle.attach(model, () => cleared += 1);
    expect(handle.dirty, false);
    model.setValue('title', 'Other');
    expect(handle.dirty, true);
    handle.reset();
    expect(cleared, 1);
    expect(handle.dirty, false);
    expect(model.valueAt('title'), 'Template');
    handle.dispose();
  });

  test('a handle whose form is not attached is never dirty and resets nothing', () {
    final handle = CruftFreeFormHandle();
    expect(handle.dirty, false);
    handle.reset();
    handle.dispose();
  });
}
